const response = $input.first().json;

const content = response.message?.content;

if (!content || typeof content !== "string") {
  throw new Error(
    `Ollama returnerede intet message.content: ${JSON.stringify(response)}`
  );
}

let parsed;

try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error(
    `Ollama returnerede ugyldig JSON: ${content}`
  );
}

if (!Array.isArray(parsed.products)) {
  throw new Error(
    `Svaret mangler products-array: ${content}`
  );
}

const expectedCount =
  $("Prepare Ollama Batch").first().json.productCount;

const expectedIds =
  $("Prepare Ollama Batch").first().json.expectedAliasIds;

if (parsed.products.length !== expectedCount) {
  throw new Error(
    `Forventede ${expectedCount} produkter, men fik ${parsed.products.length}`
  );
}

const returnedIds =
  parsed.products.map(product => Number(product.aliasId));

const missingIds =
  expectedIds.filter(id => !returnedIds.includes(Number(id)));

if (missingIds.length > 0) {
  throw new Error(
    `Ollama mangler alias-ID'er: ${missingIds.join(", ")}`
  );
}

const sourceProducts =
  $("Prepare Ollama Batch").first().json.sourceProducts;

const sourceByAliasId = new Map(
  sourceProducts.map(product => [
    Number(product.aliasId),
    product
  ])
);

return parsed.products.map(product => {
  const aliasId = Number(product.aliasId);
  const source = sourceByAliasId.get(aliasId);

  if (!source) {
    throw new Error(
      `Mangler originalt produkt for alias ${aliasId}`
    );
  }

  return {
    json: {
      ...product,
      sourceName: source.productName,
      sourceDescription: source.description,
      sourceQuantityFrom: source.quantityFrom,
      sourceQuantityTo: source.quantityTo,
      sourceUnit: source.unit,
      sourcePiecesFrom: source.piecesFrom,
      sourcePiecesTo: source.piecesTo
    }
  };
});

const product = $json;

// ---------- Hjælpefunktioner ----------

function cleanText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const cleaned = String(value)
    .trim()
    .replace(/\s+/g, " ");

  return cleaned.length > 0
    ? cleaned
    : null;
}

function cleanLowercase(value) {
  const cleaned = cleanText(value);

  return cleaned
    ? cleaned.toLocaleLowerCase("da-DK")
    : null;
}

function normalizeUnit(value) {
  const unit = cleanLowercase(value);

  if (!unit) {
    return null;
  }

  const unitMap = {
    pcs: "stk",
    pc: "stk",
    piece: "stk",
    pieces: "stk",
    styk: "stk",
    stk: "stk",

    gram: "g",
    grams: "g",
    g: "g",

    kilogram: "kg",
    kilograms: "kg",
    kilo: "kg",
    kg: "kg",

    milliliter: "ml",
    milliliters: "ml",
    ml: "ml",

    centiliter: "cl",
    centiliters: "cl",
    cl: "cl",

    deciliter: "dl",
    deciliters: "dl",
    dl: "dl",

    liter: "l",
    liters: "l",
    litre: "l",
    litres: "l",
    l: "l",

    wash: "vask",
    washes: "vask",
    vaske: "vask",
    vask: "vask"
  };

  return unitMap[unit] ?? unit;
}

function normalizeForComparison(value) {
  return String(value ?? "")
    .toLocaleLowerCase("da-DK")
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .replace(/[^a-zæøå0-9]/g, "");
}

function containsDanishTerm(text, terms) {
  const normalizedText =
    String(text ?? "")
      .toLocaleLowerCase("da-DK");

  return terms.some(term => {
    const escapedTerm = term.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    const pattern = new RegExp(
      `(^|[^a-zæøå0-9])${escapedTerm}(?=$|[^a-zæøå0-9])`,
      "iu"
    );

    return pattern.test(normalizedText);
  });
}

// ---------- Grundfelter ----------

const aliasId =
  Number(product.aliasId);

const confidence =
  Number(product.confidence);

if (
  !Number.isInteger(aliasId) ||
  aliasId <= 0
) {
  throw new Error(
    `Ugyldigt aliasId: ${product.aliasId}`
  );
}

if (
  !Number.isFinite(confidence) ||
  confidence < 0 ||
  confidence > 1
) {
  throw new Error(
    `Ugyldig confidence for alias ${aliasId}: ${product.confidence}`
  );
}

// ---------- Originale kildedata ----------

const sourceName =
  cleanText(product.sourceName) ?? "";

const sourceDescription =
  cleanText(product.sourceDescription) ?? "";

const sourceText =
  `${sourceName} ${sourceDescription}`.trim();

const sourceQuantityFrom =
  product.sourceQuantityFrom !== null &&
  product.sourceQuantityFrom !== undefined
    ? Number(product.sourceQuantityFrom)
    : null;

const sourceQuantityTo =
  product.sourceQuantityTo !== null &&
  product.sourceQuantityTo !== undefined
    ? Number(product.sourceQuantityTo)
    : null;

const sourceUnit =
  normalizeUnit(product.sourceUnit);

// ---------- Modelresultat ----------

const canonicalName =
  cleanText(product.canonicalName);

let brand =
  cleanText(product.brand);

let productType =
  cleanLowercase(product.productType);

let category =
  cleanLowercase(product.category);

const subcategory =
  cleanLowercase(product.subcategory);

let unit =
  normalizeUnit(product.unit);

let comparisonGroup =
  cleanLowercase(product.comparisonGroup);

const multiProduct =
  product.multiProduct === true;

// ---------- Mængde ----------

let quantity = null;

if (
  product.quantity !== null &&
  product.quantity !== undefined
) {
  const parsedQuantity =
    Number(product.quantity);

  if (
    Number.isFinite(parsedQuantity) &&
    parsedQuantity > 0
  ) {
    quantity = parsedQuantity;
  }
}

const sourceHasQuantityRange =
  Number.isFinite(sourceQuantityFrom) &&
  Number.isFinite(sourceQuantityTo) &&
  sourceQuantityFrom > 0 &&
  sourceQuantityTo > 0 &&
  sourceQuantityFrom !== sourceQuantityTo;

if (sourceHasQuantityRange) {
  quantity = null;
}

// ---------- Obligatoriske felter ----------

if (!canonicalName) {
  throw new Error(
    `Alias ${aliasId} mangler canonicalName`
  );
}

if (!productType) {
  throw new Error(
    `Alias ${aliasId} mangler productType`
  );
}

if (!category) {
  throw new Error(
    `Alias ${aliasId} mangler category`
  );
}

if (multiProduct) {
  comparisonGroup = null;
}

// ---------- Automatiske korrektioner ----------

const automaticCorrections = [];

function applyCategory(
  expectedCategory,
  reason
) {
  if (
    expectedCategory &&
    category !== expectedCategory
  ) {
    automaticCorrections.push(
      `Kategori ændret fra "${category}" til "${expectedCategory}": ${reason}`
    );

    category = expectedCategory;
  }
}

function applyComparisonGroup(
  expectedGroup,
  reason
) {
  if (
    !multiProduct &&
    expectedGroup &&
    comparisonGroup !== expectedGroup
  ) {
    automaticCorrections.push(
      `Comparison group ændret fra "${comparisonGroup}" til "${expectedGroup}": ${reason}`
    );

    comparisonGroup = expectedGroup;
  }
}

/*
 * Faste regler bruges kun for produkttyper,
 * der entydigt tilhører én kategori.
 */
const categoryByProductType = new Map([
  ["vin", "drikkevarer"],
  ["øl", "drikkevarer"],
  ["sodavand", "drikkevarer"],
  ["iskaffe", "drikkevarer"],
  ["instant kaffe", "drikkevarer"],
  ["energidrik", "drikkevarer"],
  ["kondi booster", "drikkevarer"],

  ["yoghurt", "mejeri og køl"],
  ["skyr", "mejeri og køl"],
  ["mælk", "mejeri og køl"],
  ["skummetmælk", "mejeri og køl"],
  ["letmælk", "mejeri og køl"],
  ["sødmælk", "mejeri og køl"],
  ["kærnemælk", "mejeri og køl"],
  ["økologisk kærnemælk", "mejeri og køl"],
  ["creme fraiche", "mejeri og køl"],
  ["flødeost", "mejeri og køl"],
  ["ost", "mejeri og køl"],
  ["skiveost", "mejeri og køl"],
  ["skæreost", "mejeri og køl"],
  ["flødekartofler", "mejeri og køl"],

  ["brød", "brød og bager"],
  ["rugbrød", "brød og bager"],
  ["boller", "brød og bager"],

  ["is", "frost"],

  ["chips", "slik og snacks"],
  ["proteinbar", "slik og snacks"],
  ["slik", "slik og snacks"],
  ["chokolade", "slik og snacks"],
  ["kugler", "slik og snacks"],

  ["pålæg", "kød og fjerkræ"],
  ["leverpostej", "kød og fjerkræ"],
  ["dansk kylling", "kød og fjerkræ"],
  ["kylling", "kød og fjerkræ"],
  ["kyllingebryst", "kød og fjerkræ"],
  [
    "marineret kyllingebryst",
    "kød og fjerkræ"
  ],
  ["hakket oksekød", "kød og fjerkræ"],
  ["hakket grisekød", "kød og fjerkræ"],

  ["blommer", "frugt og grønt"],
  ["kartofler", "frugt og grønt"],

  ["pasta", "kolonial"],
  ["ris", "kolonial"],
  ["majs", "kolonial"],
  ["olivenolie", "kolonial"],
  ["kokosmælk", "kolonial"],
  ["havregryn", "kolonial"],
  ["fras", "kolonial"],
  ["fastfood dressing", "kolonial"],
  ["dressing", "kolonial"],
  ["survarer", "kolonial"],
  ["topping", "kolonial"],
  ["sirup", "kolonial"],

  [
    "opvasketabs",
    "husholdning og rengøring"
  ],
  [
    "flydende vaskemiddel",
    "husholdning og rengøring"
  ],
  [
    "vaskepulver",
    "husholdning og rengøring"
  ],

  ["strømper", "andet"],
  ["airfryer", "andet"],
  ["bademåtte", "andet"],
  ["lampe", "andet"],
  ["opbevaringskurve", "andet"],
  ["blyantsæt", "andet"],
  ["puslespilsbog", "andet"]
]);

const deterministicCategory =
  categoryByProductType.get(productType);

if (deterministicCategory) {
  applyCategory(
    deterministicCategory,
    `fast regel for productType "${productType}"`
  );
}

/*
 * Nogle kendte typer skal have en stabil,
 * ikke-mærkespecifik comparison group.
 */
const comparisonGroupByProductType = new Map([
  ["blommer", "blommer"],
  ["chips", "chips"],
  ["yoghurt", "yoghurt"],
  ["skyr", "skyr"],
  ["pizza", "pizza"],
  ["majs", "majs"],
  ["flødekartofler", "flødekartofler"],
  ["opvasketabs", "opvasketabs"]
]);

const deterministicComparisonGroup =
  comparisonGroupByProductType.get(productType);

if (deterministicComparisonGroup) {
  applyComparisonGroup(
    deterministicComparisonGroup,
    `fast regel for productType "${productType}"`
  );
}

// Pizza afhænger af opbevaringsformen.

if (productType === "pizza") {
  if (
    /\b(?:dyb[\s-]?frost|frossen|frostvare)\b/iu.test(
      sourceText
    )
  ) {
    applyCategory(
      "frost",
      "produktteksten angiver frost"
    );
  } else if (
    /\b(?:findes på køl|på køl|kølevare)\b/iu.test(
      sourceText
    )
  ) {
    applyCategory(
      "mejeri og køl",
      "produktteksten angiver køl"
    );
  }
}

/*
 * Generisk vaskemiddel, der sælges i volumen,
 * behandles som flydende vaskemiddel.
 */
const sourceMentionsLiquidVolume =
  /\b\d+(?:[.,]\d+)?\s*(?:ml|cl|dl|l|liter)\b/iu
    .test(sourceText);

if (
  !multiProduct &&
  productType === "vaskemiddel" &&
  sourceMentionsLiquidVolume
) {
  automaticCorrections.push(
    'productType ændret fra "vaskemiddel" til "flydende vaskemiddel"'
  );

  productType =
    "flydende vaskemiddel";

  applyCategory(
    "husholdning og rengøring",
    "flydende vaskemiddel"
  );

  applyComparisonGroup(
    "flydende vaskemiddel",
    "vaskemiddel i volumen"
  );
}

// ---------- Tilladte kategorier ----------

const allowedCategories = new Set([
  "frugt og grønt",
  "kød og fjerkræ",
  "fisk og skaldyr",
  "mejeri og køl",
  "brød og bager",
  "kolonial",
  "frost",
  "drikkevarer",
  "slik og snacks",
  "husholdning og rengøring",
  "personlig pleje",
  "baby",
  "kæledyr",
  "blomster og planter",
  "andet"
]);

// ---------- For brede betegnelser ----------

const forbiddenProductTypes = new Set([
  "mad",
  "mad og drikke",
  "fødevarer",
  "dagligvarer",
  "produkt",
  "varer",
  "diverse",
  "kød",
  "fisk",
  "salat",
  "rengøring",
  "vaskemiddel",
  "drikke",
  "mejeri"
]);

const forbiddenComparisonGroups = new Set([
  "mad",
  "mad og drikke",
  "fødevarer",
  "dagligvarer",
  "produkt",
  "varer",
  "diverse",
  "kød",
  "fisk",
  "salat",
  "rengøring",
  "vaskemiddel",
  "drikke",
  "mejeri"
]);

// ---------- Kendte semantiske grupper ----------

const fruitTerms = [
  "blomme",
  "blommer",
  "æble",
  "æbler",
  "pære",
  "pærer",
  "banan",
  "bananer",
  "appelsin",
  "appelsiner",
  "citron",
  "citroner",
  "lime",
  "kiwi",
  "mango",
  "melon",
  "meloner",
  "drue",
  "druer",
  "fersken",
  "ferskner",
  "nektarin",
  "nektariner",
  "jordbær",
  "hindbær",
  "blåbær"
];

const flowerTerms = [
  "blomst",
  "blomster",
  "buket",
  "buketter",
  "rose",
  "roser",
  "tulipan",
  "tulipaner",
  "plante",
  "planter"
];

// ---------- Valideringsårsager ----------

const validationReasons = [];

const validCategory =
  allowedCategories.has(category);

if (!validCategory) {
  validationReasons.push(
    `Ikke-godkendt kategori: ${category}`
  );
}

const validProductType =
  !forbiddenProductTypes.has(productType);

if (!validProductType) {
  validationReasons.push(
    `For bred productType: ${productType}`
  );
}

const validComparisonGroup =
  comparisonGroup !== null &&
  !forbiddenComparisonGroups.has(
    comparisonGroup
  );

if (
  !multiProduct &&
  !validComparisonGroup
) {
  validationReasons.push(
    comparisonGroup === null
      ? "Mangler comparisonGroup"
      : `For bred comparisonGroup: ${comparisonGroup}`
  );
}

if (confidence < 0.85) {
  validationReasons.push(
    `Lav confidence: ${confidence}`
  );
}

// ---------- Kontrol af mærke ----------

const normalizedBrand =
  normalizeForComparison(brand);

const normalizedSource =
  normalizeForComparison(sourceText);

const invalidBrandValues = new Set([
  "ubekendt",
  "ukendt",
  "varierende",
  "varieret",
  "andet",
  "ingen",
  "udenmærke"
]);

const brandIsUnsupported =
  normalizedBrand.length > 0 &&
  (
    invalidBrandValues.has(normalizedBrand) ||
    (
      normalizedBrand.length > 2 &&
      !normalizedSource.includes(
        normalizedBrand
      )
    )
  );

if (brandIsUnsupported) {
  brand = null;
}

// ---------- Semantiske kategorikontroller ----------

/*
 * Kun hovedproduktets identitet kontrolleres.
 * Smagsord og ingredienser i beskrivelsen må ikke
 * ændre produktets hovedkategori.
 */
/*
 * productType repræsenterer hovedproduktet.
 * canonicalName kan indeholde smag, marinade og ingredienser
 * som citron, mango eller jordbær.
 */
const productIdentityText =
  productType ?? "";

const identityContainsFruit =
  containsDanishTerm(
    productIdentityText,
    fruitTerms
  );

const identityContainsFlowers =
  containsDanishTerm(
    productIdentityText,
    flowerTerms
  );

if (
  identityContainsFruit &&
  !identityContainsFlowers &&
  category !== "frugt og grønt"
) {
  validationReasons.push(
    `Frugt er placeret i forkert kategori: ${category}`
  );
}

if (
  identityContainsFlowers &&
  !identityContainsFruit &&
  category !== "blomster og planter"
) {
  validationReasons.push(
    `Blomster eller planter er placeret i forkert kategori: ${category}`
  );
}

if (
  containsDanishTerm(
    productIdentityText,
    ["blomme", "blommer"]
  ) &&
  containsDanishTerm(
    productType,
    ["blomst", "blomster"]
  )
) {
  validationReasons.push(
    "Blommer er fejlagtigt klassificeret som blomster"
  );
}

// ---------- Kontrol af mængde og enhed ----------

if (
  quantity !== null &&
  unit === null
) {
  validationReasons.push(
    "Har quantity, men mangler unit"
  );
}

if (
  sourceHasQuantityRange &&
  sourceUnit !== null &&
  unit === null
) {
  validationReasons.push(
    `Kilden har enheden ${sourceUnit}, men modellen har fjernet den`
  );
}

const sourceMentionsWashes =
  /\b\d+(?:[.,]\d+)?(?:\s*(?:-|–|—|til)\s*\d+(?:[.,]\d+)?)?\s*vaske?\b/iu
    .test(sourceText);

if (
  sourceMentionsWashes &&
  productType.includes("vaskemiddel")
) {
  if (unit !== "vask") {
    validationReasons.push(
      "Vaskemiddel med oplyst antal vaske bruger ikke enheden vask"
    );
  }

  /*
   * Ved et vaskeinterval må aliaset ikke gemme
   * én enkelt quantity.
   */
  const washRange =
    /\b\d+(?:[.,]\d+)?\s*(?:-|–|—|til)\s*\d+(?:[.,]\d+)?\s*vaske?\b/iu
      .test(sourceText);

  if (washRange) {
    quantity = null;
  }
}

// ---------- Status ----------

let normalizationStatus;

if (multiProduct) {
  normalizationStatus =
    "multi_product";
} else if (
  confidence >= 0.85 &&
  validCategory &&
  validProductType &&
  validComparisonGroup &&
  validationReasons.length === 0
) {
  normalizationStatus =
    "matched";
} else {
  normalizationStatus =
    "review";
}

// ---------- Output ----------

return {
  json: {
    aliasId,
    sourceName,
    sourceDescription,

    canonicalName,
    brand,
    productType,
    category,
    subcategory,
    comparisonGroup,
    quantity,
    unit,
    multiProduct,
    confidence,

    normalizationStatus,
    validationReasons,
    automaticCorrections,

    agentResult: {
      ...product,

      sourceName,
      sourceDescription,

      canonicalName,
      brand,
      productType,
      category,
      subcategory,
      comparisonGroup,
      quantity,
      unit,
      multiProduct,
      confidence,

      normalizationStatus,
      validationReasons,
      automaticCorrections
    }
  }
};
